/*
 * GRADUATION 09 — GRADUATION HALL
 * 25 seconds | 1 scene | 3840 x 2160 | 60 fps | seamless loop
 * Standalone, asset-free Canvas 2D. The time argument is in SECONDS.
 * Export target: 100,000,000 bits/second, configured in the video encoder.
 * Canvas JavaScript cannot enforce or measure an encoded MP4 bitrate.
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const p = sceneProgress + currentScene;
  const s = sceneProgress * sceneDuration;
  const phase = TAU * p;
  const clamp = (v) => Math.max(0, Math.min(1, v));
  const smooth = (v) => {
    const q = clamp(v);
    return q * q * q * (q * (q * 6 - 15) + 10);
  };
  function gate(a, b, c, d) {
    return smooth((s - a) / (b - a)) * (1 - smooth((s - c) / (d - c)));
  }
  function roundedRect(x, y, w, h, radius) {
    const r = Math.min(radius, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function polygon(points) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
  }
  function circle(x, y, r, fill) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    ctx.fillStyle = fill;
    ctx.fill();
  }
  function mix(a, b, q) {
    const f = clamp(q);
    return "rgb(" + a.map((v, i) => Math.round(v + (b[i] - v) * f)).join(",") + ")";
  }
  function cap(x, y, scale, color, edge) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(scale, scale);
    ctx.beginPath();
    ctx.moveTo(-24, 1);
    ctx.lineTo(-24, 17);
    ctx.quadraticCurveTo(0, 29, 24, 17);
    ctx.lineTo(24, 1);
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    polygon([[-40,-7],[0,-25],[40,-7],[0,11]]);
    ctx.fillStyle = color;
    ctx.fill();
    ctx.strokeStyle = edge;
    ctx.lineWidth = 2.1;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, -7);
    ctx.quadraticCurveTo(18, -10, 31, -2);
    ctx.lineTo(31, 21);
    ctx.strokeStyle = color;
    ctx.lineWidth = 2.5;
    ctx.stroke();
    circle(31, 24, 3, color);
    ctx.restore();
  }

  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = "source-over";
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    ctx.shadowColor = "rgba(0,0,0,0)";
    ctx.setLineDash([]);
    ctx.lineDashOffset = 0;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.miterLimit = 2;

    // A static, linear dark aesthetic gradient. No glow, halo or blur.
    const background = ctx.createLinearGradient(0, height, width, 0);
    background.addColorStop(0, "#0E1523");
    background.addColorStop(0.54, "#24283F");
    background.addColorStop(1, "#1C1D31");
    ctx.fillStyle = background;
    ctx.fillRect(0, 0, width, height);

    const unit = Math.min(minSide / 925, width / 1170);
    ctx.translate(width * 0.5, height * 0.5);
    ctx.scale(unit, unit);
    ctx.translate(0, -10);

    const ink = "#182A3C";
    const gold = "#D3BA86";
    const paleGold = "#EBD7AD";
    const ivory = "#E6DFCA";
    const doorOpen = gate(6, 10.8, 19, 24.2);
    const unroll = gate(13, 16, 19.2, 24.6);

    // The front elevation stays rigid and symmetric throughout the loop.
    roundedRect(-394, -105, 788, 385, 5);
    const wall = ctx.createLinearGradient(0, -105, 0, 280);
    wall.addColorStop(0, "#58758D");
    wall.addColorStop(1, "#405C75");
    ctx.fillStyle = wall;
    ctx.fill();
    ctx.strokeStyle = ink;
    ctx.lineWidth = 5.5;
    ctx.stroke();
    roundedRect(-394, 58, 788, 10, 2);
    ctx.fillStyle = "#718797";
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(-391, 68);
    ctx.lineTo(391, 68);
    ctx.strokeStyle = "#344E65";
    ctx.lineWidth = 2;
    ctx.stroke();

    // Four framed windows. Every pane changes only its flat fill color;
    // light is never emitted into the surrounding wall or background.
    for (const side of [-1, 1]) {
      for (let row = 0; row < 2; row++) {
        const cx = side * 237;
        const cy = row === 0 ? -4 : 145;
        const group = row * 2 + (side > 0 ? 1 : 0);
        roundedRect(cx - 53, cy - 44, 106, 88, 8);
        ctx.fillStyle = "#2A455E";
        ctx.fill();
        ctx.strokeStyle = ink;
        ctx.lineWidth = 3.5;
        ctx.stroke();
        let pane = 0;
        for (const x of [-25.5, 25.5]) for (const y of [-19.5, 19.5]) {
          const start = 0.3 + group * 1.1 + pane * 0.18;
          const activation = gate(start, start + 1.7, 20 + group * 0.25, 24.8);
          const flow = 0.5 + 0.5 * Math.sin(phase * 2 + group * 0.6 + pane * 0.4);
          const power = 0.10 + 0.72 * activation + 0.06 * flow;
          roundedRect(cx + x - 19.5, cy + y - 14, 39, 28, 3);
          ctx.fillStyle = mix([100,128,149], [218,198,153], power);
          ctx.fill();
          pane++;
        }
        roundedRect(cx - 59, cy + 41, 118, 10, 2);
        ctx.fillStyle = "#B8B7A4";
        ctx.fill();
        ctx.strokeStyle = "#425B6E";
        ctx.lineWidth = 2;
        ctx.stroke();
      }
      // Three small ventilation slots sit in the lower wall of each wing.
      ctx.beginPath();
      for (const offset of [-16, 0, 16]) {
        ctx.moveTo(side * 237 + offset, 222);
        ctx.lineTo(side * 237 + offset, 236);
      }
      ctx.strokeStyle = "#8C9A9C";
      ctx.lineWidth = 3;
      ctx.stroke();
    }

    // Central portal. Sliding panels are clipped into real side pockets,
    // keeping all moving door parts clear of the columns and facade.
    roundedRect(-83, 80, 166, 182, 8);
    ctx.fillStyle = "#C5C6B6";
    ctx.fill();
    ctx.strokeStyle = ink;
    ctx.lineWidth = 4;
    ctx.stroke();
    roundedRect(-70, 94, 140, 153, 3);
    ctx.fillStyle = "#243B50";
    ctx.fill();
    ctx.save();
    roundedRect(-70, 94, 140, 153, 3);
    ctx.clip();
    polygon([[-53,140],[0,122],[53,140],[53,198],[0,223],[-53,198]]);
    ctx.fillStyle = "#355472";
    ctx.fill();
    ctx.strokeStyle = "#B4A781";
    ctx.lineWidth = 1.7;
    ctx.stroke();
    cap(0, 170, 1.05, paleGold, "#355472");
    for (const side of [-1, 1]) {
      const x = (side < 0 ? -70 : 0) + side * 72 * doorOpen;
      roundedRect(x, 94, 70, 153, 2);
      const panel = ctx.createLinearGradient(0, 94, 0, 247);
      panel.addColorStop(0, "#47677B");
      panel.addColorStop(1, "#36546B");
      ctx.fillStyle = panel;
      ctx.fill();
      ctx.strokeStyle = "#1C3449";
      ctx.lineWidth = 2.2;
      ctx.stroke();
      roundedRect(x + 10, 108, 50, 60, 3);
      ctx.strokeStyle = "#738C96";
      ctx.lineWidth = 1.7;
      ctx.stroke();
      roundedRect(x + (side < 0 ? 59 : 7), 179, 4, 19, 2);
      ctx.fillStyle = gold;
      ctx.fill();
    }
    ctx.restore();
    roundedRect(-70, 94, 140, 153, 3);
    ctx.strokeStyle = "#A8AF9F";
    ctx.lineWidth = 2;
    ctx.stroke();

    // Four fixed columns. Shafts extend into capitals and foot blocks,
    // whose opaque fills provide clean, intentional architectural joins.
    for (const x of [-335, -140, 140, 335]) {
      roundedRect(x - 16, -66, 32, 323, 3);
      const column = ctx.createLinearGradient(0, -66, 0, 257);
      column.addColorStop(0, "#EAE3CE");
      column.addColorStop(1, "#CCCBB9");
      ctx.fillStyle = column;
      ctx.fill();
      ctx.strokeStyle = "#586C79";
      ctx.lineWidth = 2.6;
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(x - 6, -48);
      ctx.lineTo(x - 6, 239);
      ctx.moveTo(x + 6, -48);
      ctx.lineTo(x + 6, 239);
      ctx.strokeStyle = "#B5B8A7";
      ctx.lineWidth = 1.5;
      ctx.stroke();
      roundedRect(x - 26, -78, 52, 18, 3);
      ctx.fillStyle = ivory;
      ctx.fill();
      ctx.strokeStyle = "#586C79";
      ctx.lineWidth = 2.5;
      ctx.stroke();
      roundedRect(x - 26, 248, 52, 20, 3);
      ctx.fillStyle = "#D5D2BF";
      ctx.fill();
      ctx.strokeStyle = "#586C79";
      ctx.lineWidth = 2.5;
      ctx.stroke();
    }

    // The banner is fed downward from two fixed anchors. The pattern is
    // revealed by clipping; it is never vertically stretched.
    for (const x of [-108, 108]) {
      ctx.beginPath();
      ctx.moveTo(x, -54);
      ctx.lineTo(x, -44);
      ctx.strokeStyle = gold;
      ctx.lineWidth = 3;
      ctx.stroke();
      circle(x, -55, 4.5, paleGold);
    }
    const rollY = -48 + 15 + 57 * unroll;
    const wave = 2.2 * unroll * Math.sin(phase * 2 - 0.4);
    function bannerPath() {
      ctx.beginPath();
      ctx.moveTo(-108, -48);
      ctx.lineTo(108, -48);
      ctx.lineTo(108, rollY);
      ctx.bezierCurveTo(44, rollY + wave * 2, -44, rollY - wave * 2, -108, rollY);
      ctx.closePath();
    }
    bannerPath();
    const banner = ctx.createLinearGradient(0, -48, 0, 26);
    banner.addColorStop(0, "#3B587B");
    banner.addColorStop(1, "#2B4261");
    ctx.fillStyle = banner;
    ctx.fill();
    ctx.save();
    bannerPath();
    ctx.clip();
    ctx.beginPath();
    ctx.moveTo(-94, -41);
    ctx.lineTo(94, -41);
    ctx.strokeStyle = gold;
    ctx.lineWidth = 1.7;
    ctx.stroke();
    polygon([[0,-29],[16,-15],[0,-1],[-16,-15]]);
    ctx.fillStyle = paleGold;
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(-76, -15);
    ctx.lineTo(-34, -15);
    ctx.moveTo(34, -15);
    ctx.lineTo(76, -15);
    ctx.strokeStyle = "#CFB88B";
    ctx.lineWidth = 2.2;
    ctx.stroke();
    ctx.globalAlpha = unroll;
    ctx.beginPath();
    ctx.moveTo(-96, rollY - 6);
    ctx.bezierCurveTo(-40, rollY - 6 - wave, 40, rollY - 6 + wave, 96, rollY - 6);
    ctx.strokeStyle = gold;
    ctx.lineWidth = 1.8;
    ctx.stroke();
    ctx.restore();
    bannerPath();
    ctx.strokeStyle = "#243C57";
    ctx.lineWidth = 3;
    ctx.stroke();

    // Pediment and entablature remain fixed over the column attachments.
    polygon([[-440,-118],[0,-306],[440,-118]]);
    const roof = ctx.createLinearGradient(0, -306, 0, -118);
    roof.addColorStop(0, "#6D879C");
    roof.addColorStop(1, "#4D6983");
    ctx.fillStyle = roof;
    ctx.fill();
    ctx.strokeStyle = ink;
    ctx.lineWidth = 5.5;
    ctx.stroke();
    polygon([[-381,-123],[0,-285],[381,-123]]);
    ctx.strokeStyle = "#C1B58F";
    ctx.lineWidth = 2;
    ctx.stroke();
    roundedRect(-430, -129, 860, 37, 5);
    ctx.fillStyle = "#B9C1B8";
    ctx.fill();
    ctx.strokeStyle = ink;
    ctx.lineWidth = 4;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-410, -115);
    ctx.lineTo(410, -115);
    ctx.strokeStyle = "#E0D7BC";
    ctx.lineWidth = 2;
    ctx.stroke();

    // Generic academic crest, made entirely from original vector paths.
    const shield = [[0,-260],[80,-240],[80,-188],[0,-157],[-80,-188],[-80,-240]];
    polygon(shield);
    ctx.fillStyle = "#344D6C";
    ctx.fill();
    ctx.strokeStyle = "#BDA77B";
    ctx.lineWidth = 2.4;
    ctx.stroke();
    let perimeter = 0;
    for (let i = 0; i < shield.length; i++) {
      const a = shield[i];
      const b = shield[(i + 1) % shield.length];
      perimeter += Math.hypot(a[0] - b[0], a[1] - b[1]);
    }
    polygon(shield);
    ctx.setLineDash([31, perimeter - 31]);
    ctx.lineDashOffset = -perimeter * p;
    ctx.strokeStyle = "#EAD4A6";
    ctx.lineWidth = 1.9;
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.lineDashOffset = 0;
    cap(0, -214, 1.2, paleGold, "#344D6C");

    // Three overlapping front step slabs form one clean, connected base.
    const steps = [[-421,269,842,27],[-436,292,872,24],[-458,312,916,22]];
    const colors = ["#B7BCAF", "#9DAAA8", "#80949D"];
    for (let i = 0; i < steps.length; i++) {
      const a = steps[i];
      roundedRect(a[0], a[1], a[2], a[3], 4);
      ctx.fillStyle = colors[i];
      ctx.fill();
      ctx.strokeStyle = ink;
      ctx.lineWidth = 3.5;
      ctx.stroke();
    }
  } finally {
    ctx.restore();
    ctx.beginPath();
  }
}

draw.duration = 25;
draw.sceneCount = 1;
draw.fps = 60;
draw.exportSettings = {
  width: 3840,
  height: 2160,
  fps: 60,
  duration: 25,
  videoBitrate: 100000000,
  minVideoBitrate: 100000000,
  maxVideoBitrate: 100000000,
  bitrateMode: "CBR"
};

/*
 * GRADUATION 10 — LAUNCH YOUR FUTURE
 * 25 seconds | 1 scene | 3840 x 2160 | 60 fps | seamless loop
 * Standalone, asset-free Canvas 2D. The time argument is in SECONDS.
 * Export target: 100,000,000 bits/second, configured in the video encoder.
 * Canvas JavaScript cannot enforce or measure an encoded MP4 bitrate.
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const p = sceneProgress + currentScene;
  const s = sceneProgress * sceneDuration;
  const phase = TAU * p;
  const clamp = (v) => Math.max(0, Math.min(1, v));
  const smooth = (v) => {
    const q = clamp(v);
    return q * q * q * (q * (q * 6 - 15) + 10);
  };
  function gate(a, b, c, d) {
    return smooth((s - a) / (b - a)) * (1 - smooth((s - c) / (d - c)));
  }
  function keys(points) {
    for (let i = 1; i < points.length; i++) {
      if (p <= points[i][0]) {
        const a = points[i - 1];
        const b = points[i];
        return a[1] + (b[1] - a[1]) * smooth((p - a[0]) / (b[0] - a[0]));
      }
    }
    return points[points.length - 1][1];
  }
  function roundedRect(x, y, w, h, radius) {
    const r = Math.min(radius, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function polygon(points) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
  }
  function circle(x, y, r, fill, stroke, lineWidth) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) {
      ctx.strokeStyle = stroke;
      ctx.lineWidth = lineWidth;
      ctx.stroke();
    }
  }
  function bodyPath() {
    ctx.beginPath();
    ctx.moveTo(0, -307);
    ctx.bezierCurveTo(-82, -256, -120, -168, -116, -56);
    ctx.lineTo(-107, 95);
    ctx.quadraticCurveTo(-102, 132, -82, 147);
    ctx.lineTo(82, 147);
    ctx.quadraticCurveTo(102, 132, 107, 95);
    ctx.lineTo(116, -56);
    ctx.bezierCurveTo(120, -168, 82, -256, 0, -307);
    ctx.closePath();
  }
  function finPath(side) {
    ctx.beginPath();
    ctx.moveTo(side * -98, -24);
    ctx.bezierCurveTo(side * -145, 6, side * -179, 57, side * -186, 128);
    ctx.quadraticCurveTo(side * -186, 144, side * -170, 139);
    ctx.lineTo(side * -100, 108);
    ctx.lineTo(side * -83, 35);
    ctx.closePath();
  }
  function flamePath(base, length, halfWidth, bend) {
    ctx.beginPath();
    ctx.moveTo(-halfWidth, base);
    ctx.bezierCurveTo(
      -halfWidth * 1.12, base + length * 0.20,
      -halfWidth * 1.05 + bend * 0.15, base + length * 0.44,
      -halfWidth * 0.62 + bend * 0.4, base + length * 0.64
    );
    ctx.bezierCurveTo(
      -halfWidth * 0.42 + bend * 0.6, base + length * 0.80,
      -halfWidth * 0.20 + bend * 0.9, base + length * 0.93,
      bend, base + length
    );
    ctx.bezierCurveTo(
      halfWidth * 0.20 + bend * 0.9, base + length * 0.93,
      halfWidth * 0.42 + bend * 0.6, base + length * 0.80,
      halfWidth * 0.62 + bend * 0.4, base + length * 0.64
    );
    ctx.bezierCurveTo(
      halfWidth * 1.05 + bend * 0.15, base + length * 0.44,
      halfWidth * 1.12, base + length * 0.20,
      halfWidth, base
    );
    ctx.closePath();
  }

  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = "source-over";
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    ctx.shadowColor = "rgba(0,0,0,0)";
    ctx.setLineDash([]);
    ctx.lineDashOffset = 0;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.miterLimit = 2;

    // Static linear ink-blue background. No glow, blur, stars or halos.
    const background = ctx.createLinearGradient(0, height, width, 0);
    background.addColorStop(0, "#0B1423");
    background.addColorStop(0.54, "#1B2B43");
    background.addColorStop(1, "#181E35");
    ctx.fillStyle = background;
    ctx.fillRect(0, 0, width, height);

    const unit = Math.min(minSide / 960, width / 980);
    const power = keys([[0,0.48],[0.24,0.96],[0.52,1],[0.76,0.78],[1,0.48]]);
    const heightOffset = keys([[0,18],[0.24,-28],[0.52,-44],[0.76,-20],[1,18]]);
    const celebration = gate(12, 14.5, 18.7, 23.5);
    ctx.translate(width * 0.5, height * 0.5);
    ctx.scale(unit, unit);
    ctx.translate(14 * Math.sin(phase) + 3 * Math.sin(phase * 2), heightOffset + 2.5 * Math.sin(phase * 3));
    ctx.rotate(0.018 * Math.sin(phase) + 0.006 * Math.sin(phase * 2));

    const ink = "#15283F";
    const gold = "#DFC695";
    const paleGold = "#F1DDB4";

    // Four short motion cues use dedicated outer lanes, clear of the fins.
    // Their opacity and its slope are zero whenever a cue wraps.
    for (const side of [-1, 1]) for (let i = 0; i < 2; i++) {
      const q = (p * 4 + i * 0.36 + (side > 0 ? 0.17 : 0)) % 1;
      const x = side * (228 + i * 24);
      const y = -150 + 330 * q;
      ctx.globalAlpha = 0.32 * power * Math.pow(Math.sin(Math.PI * q), 2);
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x, y + 15 + i * 6);
      ctx.strokeStyle = "#6F8BA4";
      ctx.lineWidth = 2.2;
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    // Three coherent exhaust layers share one fixed engine attachment.
    // They change length gently with thrust, without opacity flicker.
    const length = 132 + power * 54 + 3 * Math.sin(phase * 10);
    const bend = 3.6 * power * Math.sin(phase * 3 - 0.5);
    const exhaust = [
      [length,43,bend,"#9A84B1","#73739F"],
      [length*0.78,30,bend*0.62,"#D9AC95","#C28D80"],
      [length*0.53,17,bend*0.32,"#F2DEB8","#E2BC8A"]
    ];
    for (let i = 0; i < exhaust.length; i++) {
      const a = exhaust[i];
      flamePath(178, a[0], a[1], a[2]);
      const fill = ctx.createLinearGradient(0, 178, 0, 178 + a[0]);
      fill.addColorStop(0, a[3]);
      fill.addColorStop(1, a[4]);
      ctx.fillStyle = fill;
      ctx.fill();
      if (i === 0) {
        ctx.strokeStyle = ink;
        ctx.lineWidth = 4.2;
        ctx.stroke();
      }
    }

    // Engine and fins are behind the body; the body covers their joins.
    ctx.beginPath();
    ctx.moveTo(-76, 139);
    ctx.lineTo(-63, 182);
    ctx.quadraticCurveTo(0, 199, 63, 182);
    ctx.lineTo(76, 139);
    ctx.closePath();
    const engine = ctx.createLinearGradient(0, 139, 0, 191);
    engine.addColorStop(0, "#456A87");
    engine.addColorStop(1, "#34536E");
    ctx.fillStyle = engine;
    ctx.fill();
    ctx.strokeStyle = ink;
    ctx.lineWidth = 5;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-53, 178);
    ctx.quadraticCurveTo(0, 190, 53, 178);
    ctx.strokeStyle = "#8CA9B3";
    ctx.lineWidth = 2;
    ctx.stroke();

    const fin = ctx.createLinearGradient(0, -24, 0, 145);
    fin.addColorStop(0, "#8377AA");
