    ctx.lineWidth = 4.3;
    ctx.stroke();

    circle(0, 3, 11, gold, ink, 3.5);
    roundedRect(-14, 12, 28, 21, 5);
    ctx.fillStyle = "#C59E61";
    ctx.fill();
    ctx.strokeStyle = ink;
    ctx.lineWidth = 3.5;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-9, 18);
    ctx.lineTo(9, 18);
    ctx.moveTo(-9, 25);
    ctx.lineTo(9, 25);
    ctx.strokeStyle = paleGold;
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.restore();
  } finally {
    ctx.restore();
    ctx.beginPath();
  }
}

