/*
 * GRADUATION 02 — RIBBONBOUND DIPLOMA
 * 25 seconds | one scene | 3840 x 2160 | 60 fps | seamless loop
 * Standalone, deterministic Canvas 2D. The time argument is in SECONDS.
 * All coordinates below are proportional to minSide.
 * Export requirement: 100,000,000 bits/second. Configure the video encoder;
 * Canvas drawing code cannot enforce or verify an encoded MP4 bitrate.
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const p = sceneProgress + currentScene;
  const phase = TAU * p;
  const clamp = (v) => Math.max(0, Math.min(1, v));
  const smooth = (v) => {
    const q = clamp(v);
    return q * q * q * (q * (q * 6 - 15) + 10);
  };
  function keys(points) {
    for (let i = 1; i < points.length; i++) {
      if (p <= points[i][0]) {
        const a = points[i - 1];
        const b = points[i];
        return a[1] + (b[1] - a[1]) * smooth((p - a[0]) / (b[0] - a[0]));
      }
    }
    return points[points.length - 1][1];
  }
  function roundedRect(x, y, w, h, radius) {
    const r = Math.min(radius, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function polygon(points) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
  }
  function circle(x, y, r, fill, stroke, lineWidth) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) {
      ctx.strokeStyle = stroke;
      ctx.lineWidth = lineWidth;
      ctx.stroke();
    }
  }
  function rosette(cx, cy, radius) {
    ctx.beginPath();
    for (let i = 0; i <= 96; i++) {
      const a = i / 96 * TAU - Math.PI / 2;
      const r = radius + Math.cos(a * 12) * 2.4;
      const x = cx + Math.cos(a) * r;
      const y = cy + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath();
  }
  function star(cx, cy, radius) {
    ctx.beginPath();
    for (let i = 0; i < 10; i++) {
      const a = -Math.PI / 2 + i * Math.PI / 5;
      const r = i % 2 === 0 ? radius : radius * 0.45;
      const x = cx + Math.cos(a) * r;
      const y = cy + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath();
  }

  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = "source-over";
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    ctx.shadowColor = "rgba(0,0,0,0)";
    ctx.setLineDash([]);
    ctx.lineDashOffset = 0;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.miterLimit = 2;

    // A quiet dark linear gradient, without background lighting effects.
    const background = ctx.createLinearGradient(0, height, width, 0);
    background.addColorStop(0, "#100F1B");
    background.addColorStop(0.55, "#291A2C");
    background.addColorStop(1, "#191321");
    ctx.fillStyle = background;
    ctx.fillRect(0, 0, width, height);

    const opening = keys([[0, 0], [0.24, 1], [0.48, 1], [0.76, 0.84], [1, 0]]);
    const release = keys([[0, 0], [0.24, 0.85], [0.48, 1], [0.76, 0.12], [1, 0]]);
    const document = keys([[0, 0], [0.24, 0.08], [0.48, 1], [0.76, 1], [1, 0]]);
    const halfW = 272 + opening * 170;
    const unit = Math.min(minSide / 850, width / 1260);
    const lift = keys([[0, 3], [0.24, -8], [0.48, -12], [0.76, -4], [1, 3]]);
    const tilt = 0.008 * Math.sin(phase) + 0.003 * Math.sin(phase * 2);
    ctx.translate(width * 0.5, height * 0.5);
    ctx.scale(unit, unit);
    ctx.translate(0, -8 + lift + 2 * Math.sin(phase * 3));
    ctx.rotate(tilt);

    const paperOutline = "#A98B61";
    const paperDark = "#C5AD87";
    const ink = "#644E45";
    const burgundy = "#94384F";
    const darkRibbon = "#61283D";
    const gold = "#DBB875";

    roundedRect(-halfW, -194, halfW * 2, 388, 10);
    const paper = ctx.createLinearGradient(0, -194, 0, 194);
    paper.addColorStop(0, "#FCF4E3");
    paper.addColorStop(1, "#EADBC2");
    ctx.fillStyle = paper;
    ctx.fill();
    ctx.strokeStyle = paperOutline;
    ctx.lineWidth = 5;
    ctx.stroke();

    // Document artwork is revealed by the rolling edges; it is never scaled
    // horizontally or squeezed as the visible paper width changes.
    ctx.save();
    roundedRect(-halfW + 22, -183, halfW * 2 - 44, 366, 4);
    ctx.clip();
    roundedRect(-385, -161, 770, 322, 6);
    ctx.strokeStyle = "#B69B6D";
    ctx.lineWidth = 2.4;
    ctx.stroke();
    roundedRect(-374, -150, 748, 300, 3);
    ctx.strokeStyle = "#D8C5A0";
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Quiet, geometric corner marks belong to the printed document.
    for (const side of [-1, 1]) {
      for (const vertical of [-1, 1]) {
        ctx.save();
        ctx.translate(side * 353, vertical * 129);
        ctx.scale(side, vertical);
        ctx.beginPath();
        ctx.moveTo(-20, 0);
        ctx.lineTo(0, 0);
        ctx.lineTo(0, -20);
        ctx.strokeStyle = "#B59A6A";
        ctx.lineWidth = 2.4;
        ctx.stroke();
        ctx.restore();
      }
    }

    // A generic mortarboard mark is drawn entirely with vector paths.
    ctx.save();
    ctx.translate(0, -102);
    ctx.globalAlpha = 0.52 + 0.48 * document;
    ctx.beginPath();
    ctx.moveTo(-35, 6);
    ctx.lineTo(-35, 26);
    ctx.quadraticCurveTo(0, 43, 35, 26);
    ctx.lineTo(35, 6);
    ctx.closePath();
    ctx.fillStyle = ink;
    ctx.fill();
    polygon([[-62, 0], [0, -27], [62, 0], [0, 27]]);
    ctx.fillStyle = ink;
    ctx.fill();
    ctx.strokeStyle = "#EEDDBB";
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(25, -4, 49, 6);
    ctx.lineTo(49, 34);
    ctx.strokeStyle = gold;
    ctx.lineWidth = 3;
    ctx.stroke();
    circle(49, 38, 3.5, gold);
    ctx.restore();

    // Language-neutral engraved heading and three balanced document rules.
    roundedRect(-94, -43, 188, 8, 4);
    ctx.fillStyle = "#8A6A51";
    ctx.fill();
    const lineY = [-12, 13, 38];
    const lengths = [352, 296, 224];
    for (let i = 0; i < 3; i++) {
      const len = lengths[i];
      ctx.beginPath();
      ctx.moveTo(-len / 2, lineY[i]);
      ctx.lineTo(len / 2, lineY[i]);
      ctx.strokeStyle = "#D6C4A3";
      ctx.lineWidth = 4;
      ctx.stroke();
      const localReveal = smooth((document - i * 0.14) / 0.72);
      if (localReveal > 0.00001) {
        ctx.beginPath();
        ctx.moveTo(-len / 2, lineY[i]);
        ctx.lineTo(-len / 2 + len * localReveal, lineY[i]);
        ctx.strokeStyle = i === 0 ? "#9D7B58" : "#B1956D";
        ctx.lineWidth = 4;
        ctx.stroke();
      }
    }
    ctx.restore();

    // Each edge is a flat paper curl. The printed artwork stays beneath it.
    function roll(side) {
      ctx.save();
      ctx.scale(side, 1);
      const x = -halfW;
      ctx.beginPath();
      ctx.moveTo(x + 18, -188);
      ctx.bezierCurveTo(x - 4, -213, x - 41, -201, x - 41, -174);
      ctx.lineTo(x - 41, 174);
      ctx.bezierCurveTo(x - 41, 201, x - 3, 212, x + 18, 188);
      ctx.lineTo(x + 18, -188);
      ctx.closePath();
      const rollFill = ctx.createLinearGradient(0, -200, 0, 205);
      rollFill.addColorStop(0, "#F6E8CB");
      rollFill.addColorStop(1, "#DECAA5");
      ctx.fillStyle = rollFill;
      ctx.fill();
      ctx.strokeStyle = paperOutline;
      ctx.lineWidth = 4.5;
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(x + 17, -186);
      ctx.bezierCurveTo(x + 1, -204, x - 24, -199, x - 26, -180);
      ctx.bezierCurveTo(x - 27, -165, x - 9, -158, x + 3, -169);
      ctx.moveTo(x + 17, 186);
      ctx.bezierCurveTo(x + 1, 204, x - 24, 199, x - 26, 180);
      ctx.bezierCurveTo(x - 27, 165, x - 9, 158, x + 3, 169);
      ctx.strokeStyle = paperDark;
      ctx.lineWidth = 3;
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(x - 27, -145);
      ctx.lineTo(x - 27, 145);
      ctx.strokeStyle = "#F9EFD9";
      ctx.lineWidth = 3;
      ctx.stroke();
      ctx.restore();
    }
    roll(1);
    roll(-1);

    const bowY = 103 + 1.5 * Math.sin(phase * 2);
    const ribbonY = bowY - 14;
    // The ribbon is unrolled with the paper. Its width changes by revealing
    // material at the edge, not by deforming the bow or its central seal.
    roundedRect(-halfW + 19, ribbonY, halfW * 2 - 38, 28, 5);
    const ribbonFill = ctx.createLinearGradient(0, ribbonY, 0, ribbonY + 28);
    ribbonFill.addColorStop(0, "#A2475D");
    ribbonFill.addColorStop(1, "#843348");
    ctx.fillStyle = ribbonFill;
    ctx.fill();
    ctx.strokeStyle = darkRibbon;
    ctx.lineWidth = 3;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-halfW + 29, ribbonY + 6);
    ctx.lineTo(halfW - 29, ribbonY + 6);
    ctx.strokeStyle = "#BF7786";
    ctx.lineWidth = 1.6;
    ctx.stroke();

    ctx.save();
    ctx.translate(0, bowY);

    // The tails are separate coherent ribbons, attached beneath the seal.
    // Their swept envelopes are disjoint below the knot.
    function tail(side) {
      ctx.save();
      ctx.scale(side, 1);
      const sway = 4.5 * Math.sin(phase * 3 - side * 0.45) + release * 3;
      const endY = side === 1 ? 128 : 111;
      ctx.beginPath();
      ctx.moveTo(-8, 9);
      ctx.bezierCurveTo(-22, 45, -38 + sway, 84, -47 + sway, endY);
      ctx.lineTo(-62 + sway, endY - 14);
      ctx.lineTo(-81 + sway, endY - 2);
      ctx.bezierCurveTo(-68 + sway, 81, -46, 42, -30, 6);
      ctx.closePath();
      const tailFill = ctx.createLinearGradient(-25, 10, -60, endY);
      tailFill.addColorStop(0, "#A4475D");
      tailFill.addColorStop(1, "#7C3046");
      ctx.fillStyle = tailFill;
      ctx.fill();
      ctx.strokeStyle = darkRibbon;
      ctx.lineWidth = 3.5;
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(-28, 26);
      ctx.bezierCurveTo(-40, 53, -52 + sway, 89, -57 + sway, endY - 21);
      ctx.strokeStyle = "#C17789";
      ctx.lineWidth = 1.8;
      ctx.stroke();
      ctx.restore();
    }
    tail(1);
    tail(-1);

    function bowLoop(side) {
      ctx.save();
      ctx.scale(side, 1);
      const spread = release * 17;
      const wave = 2.6 * Math.sin(phase * 2 - side * 0.32);
      ctx.beginPath();
      ctx.moveTo(-15, -3);
      ctx.bezierCurveTo(-44, -35 - release * 5, -106 - spread, -55 + wave, -116 - spread, -23 + wave);
      ctx.bezierCurveTo(-130 - spread, 13 + wave, -63, 30, -15, 8);
      ctx.closePath();
      const loopFill = ctx.createLinearGradient(0, -45, 0, 28);
      loopFill.addColorStop(0, "#B5566C");
      loopFill.addColorStop(1, burgundy);
      ctx.fillStyle = loopFill;
      ctx.fill();
      ctx.strokeStyle = darkRibbon;
      ctx.lineWidth = 3.5;
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(-27, 1);
      ctx.bezierCurveTo(-58, -10, -92 - spread, -21 + wave, -109 - spread, -20 + wave);
      ctx.strokeStyle = "#CB8495";
      ctx.lineWidth = 2.1;
      ctx.stroke();
      ctx.restore();
    }
    bowLoop(1);
    bowLoop(-1);

    // An opaque seal intentionally hides the attachment of the four ribbon
    // pieces. Its diameter, star, and spacing are fixed throughout the loop.
    rosette(0, 0, 36);
    const seal = ctx.createLinearGradient(0, -38, 0, 38);
    seal.addColorStop(0, "#E9CF96");
    seal.addColorStop(1, "#C39B58");
    ctx.fillStyle = seal;
    ctx.fill();
    ctx.strokeStyle = "#8A683D";
    ctx.lineWidth = 2.8;
    ctx.stroke();
    circle(0, 0, 26, null, "#A17C45", 2);
    star(0, 0, 15);
    ctx.fillStyle = "#916C3B";
    ctx.fill();

    // A short engraved arc travels along the existing seal rim, never
    // outside the emblem, and completes two exact turns in 25 seconds.
    ctx.beginPath();
    ctx.arc(0, 0, 30.4, phase * 2 - 0.35, phase * 2 + 0.35);
    ctx.strokeStyle = "#F7E4BA";
    ctx.lineWidth = 2.4;
    ctx.stroke();
    ctx.restore();
  } finally {
    ctx.restore();
    ctx.beginPath();
  }
}

